  function conditionsMatch(conditions: Record<string, unknown>, facts: Record<string, unknown>): boolean { for (const [key, expected] of Object.entries(conditions)) { const actual = key === "amountMin" || key === "amountMax" ? facts.amount : facts[key.endsWith("Min") || key.endsWith("Max") ? key.slice(0, -3) : key]; if (key.endsWith("Min")) { if (typeof actual !== "number" || actual < Number(expected)) return false; } else if (key.endsWith("Max")) { if (typeof actual !== "number" || actual > Number(expected)) return false; } else if (actual === undefined || String(actual).toLowerCase() !== String(expected).toLowerCase()) return false; } return true; }
