  export async function approvalHistory(p: { actor: ErpPayload; id: string }): Promise<api.IApprovalHistory[]> { const org = await AuthProvider.organizationId(p.actor); const row = await MyGlobal.prisma.approvals.findFirst({ where: { id: p.id, organization_id: org } }); if (row === null) throw ErrorUtil.notFound("No approval exists in the active organization."); const rows = await MyGlobal.prisma.approval_history.findMany({ where: { approval_id: row.id }, orderBy: { created_at: "asc" } }); return rows.map((r) => ({ id: r.id, approvalId: r.approval_id, actorMembershipId: r.actor_membership_id, action: r.action, reason: r.reason, createdAt: r.created_at.toISOString() })); }
